INSERT INTO public.telegram_enrollment_report_access(chat_id,can_manage,active,granted_by) VALUES (100554898,true,true,100554898),(1222139555,false,true,100554898) ON CONFLICT(chat_id) DO UPDATE SET can_manage=excluded.can_manage,active=true,granted_by=excluded.granted_by;
INSERT INTO public.telegram_enrollment_report_access(chat_id,can_manage,active,granted_by) SELECT DISTINCT telegram_chat_id,false,true,100554898 FROM public.chat_users WHERE telegram_chat_id>0 AND telegram_chat_id<>100554898 AND (role IN ('admin','sales_manager','support_manager','support_admin') OR is_messenger_admin=true OR id IN (SELECT user_id FROM public.user_roles WHERE is_active=true AND role_name IN ('admin','sales_manager','support_manager','support_admin'))) ON CONFLICT(chat_id) DO UPDATE SET active=true,granted_by=excluded.granted_by;